-- S106 — Bookings engine corrections (KANEL × ALCEDO online bookings, Phase 2).
--
-- Corrects the existing booking engine (s103) so the approved online rules are
-- physically valid, WITHOUT changing the private gateway pattern, RLS, grants or
-- the staff interface. All objects stay in atlas_private / the public SECURITY
-- DEFINER gateway, service_role-only.
--
-- What this migration does (engine primitives + approved values):
--   1. booking_settings: max_party_online 30 -> 4, turnaround_minutes 0 -> 15.
--   2. A real seating-segment model on the Bar: three independent, physically
--      valid sections — Bar 1-8 (A), 9-12 (B), 13-16 (C) — replacing the circular
--      ring. Adjacency may never cross 8-9, 12-13 or 16-1.
--   3. booking_find_contiguous_tables rewritten to be segment-bounded and to
--      never wrap, so auto-assignment only ever offers a run of adjacent stools
--      inside one section (corrections 5 & 6).
--   4. Staff assign/approve/reassign enforce the same rule: a multi-stool
--      allocation must be one contiguous group within a single section
--      (correction 7).
--   5. booking_day_last_start_minutes(): the per-day last start derived from each
--      day's closing time in settings_business_hours (the venue clock), allowing a
--      120-minute visit to finish by close (correction 4). The public booking
--      service (Phase 3) enforces it; staff phone/walk-in are unaffected here.
--
-- The public online party cap (4), the Bar-only restriction and the per-day
-- cutoff are enforced at the public boundary in Phase 3; this migration supplies
-- the corrected engine they build on. No production apply; public path stays
-- behind PUBLIC_BOOKING_ENABLED.

-- 1. Approved settings values ------------------------------------------------
update atlas_private.booking_settings
set max_party_online = 4,
    turnaround_minutes = 15
where id = true;

-- 2. Seating-segment model ---------------------------------------------------
-- A stool's section. NULL for areas that are not segmented (unchanged behaviour).
alter table atlas_private.booking_tables
  add column if not exists segment text;

comment on column atlas_private.booking_tables.segment is
  'Physical seating section within an area. Adjacency never crosses sections. '
  'NULL = the area is not segmented. Bar: A = stools 1-8, B = 9-12, C = 13-16.';

-- The Bar is NOT a circle: retire the wrapping flag.
update atlas_private.booking_areas
set circular_adjacency = false
where id = 'ba000000-0000-4000-8000-000000000001';

-- Assign the three Bar sections by position_index (1-8 / 9-12 / 13-16).
update atlas_private.booking_tables
set segment = case
    when position_index between 1 and 8 then 'A'
    when position_index between 9 and 12 then 'B'
    when position_index between 13 and 16 then 'C'
  end
where area_id = 'ba000000-0000-4000-8000-000000000001';

-- 3. Segment-bounded, non-wrapping contiguity -------------------------------
-- Find one run of p_party_size adjacent free stools that lies ENTIRELY inside a
-- single section. A run extends by consecutive position_index only while the
-- next stool is in the same area AND the same segment; it never wraps past the
-- last position and never crosses a section boundary (8->9, 12->13, 16->1).
create or replace function atlas_private.booking_find_contiguous_tables(
  p_area_id uuid, p_party_size integer, p_start timestamptz, p_end timestamptz,
  p_ignore_reservation uuid default null
)
returns uuid[]
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  rec record;
  start_seg text;
  start_pos integer;
  offset_i integer;
  target_pos integer;
  tid uuid;
  tseg text;
  candidate uuid[];
begin
  if p_party_size is null or p_party_size < 1 then return null; end if;

  -- Try each bookable stool as the run's first seat, in section + position order.
  for rec in
    select t.id, t.position_index as pos, t.segment as seg
    from atlas_private.booking_tables t
    where t.area_id = p_area_id and t.position_index is not null
      and t.is_bookable and not t.temporarily_unavailable
    order by t.segment nulls first, t.position_index
  loop
    start_seg := rec.seg;
    start_pos := rec.pos;
    candidate := array[]::uuid[];
    for offset_i in 0..(p_party_size - 1) loop
      target_pos := start_pos + offset_i;  -- strictly increasing: never wraps
      select t.id, t.segment into tid, tseg
      from atlas_private.booking_tables t
      where t.area_id = p_area_id and t.position_index = target_pos
        and t.is_bookable and not t.temporarily_unavailable
        and t.segment is not distinct from start_seg   -- same section (or both NULL)
        and atlas_private.booking_table_free(t.id, p_start, p_end, p_ignore_reservation);
      if tid is null then candidate := null; exit; end if;
      candidate := pg_catalog.array_append(candidate, tid);
    end loop;
    if candidate is not null and pg_catalog.array_length(candidate, 1) = p_party_size then
      return candidate;
    end if;
  end loop;
  return null;
end
$function$;
revoke all on function atlas_private.booking_find_contiguous_tables(uuid,integer,timestamptz,timestamptz,uuid)
  from public, anon, authenticated;

-- 4. Validator: a set of stools is one contiguous group inside one section ---
-- Used to gate staff assignment/approval/reassignment (correction 7). Lenient
-- for areas that are not segmented (all-NULL segment) and for single stools.
create or replace function atlas_private.booking_tables_contiguous_segment(p_table_ids uuid[])
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  n integer;
  areas integer;
  segs integer;
  null_segs integer;
  pos_min integer;
  pos_max integer;
  distinct_pos integer;
begin
  if p_table_ids is null or pg_catalog.array_length(p_table_ids, 1) is null then return false; end if;
  n := pg_catalog.array_length(p_table_ids, 1);
  if n = 1 then return true; end if;

  select pg_catalog.count(distinct t.area_id),
         pg_catalog.count(distinct t.segment),
         pg_catalog.count(*) filter (where t.segment is null),
         pg_catalog.min(t.position_index),
         pg_catalog.max(t.position_index),
         pg_catalog.count(distinct t.position_index)
    into areas, segs, null_segs, pos_min, pos_max, distinct_pos
  from atlas_private.booking_tables t
  where t.id = any(p_table_ids);

  -- All stools must exist and sit in one area.
  if areas <> 1 then return false; end if;
  -- A non-segmented area imposes no section rule.
  if null_segs = n then return true; end if;
  -- Otherwise every stool must be in the SAME section …
  if segs <> 1 or null_segs <> 0 then return false; end if;
  -- … and form a gap-free, non-repeating run of consecutive positions.
  if pos_min is null or pos_max is null then return false; end if;
  return distinct_pos = n and (pos_max - pos_min + 1) = n;
end
$function$;
revoke all on function atlas_private.booking_tables_contiguous_segment(uuid[])
  from public, anon, authenticated;

-- Re-create staff assign with the section-contiguity guard added (otherwise the
-- s103 body is preserved verbatim).
create or replace function public.atlas_bookings_assign(
  p_actor_id uuid, p_actor_role text, p_reservation_id uuid, p_table_ids jsonb
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  label text := atlas_private.booking_require_staff(p_actor_id, p_actor_role);
  r atlas_private.reservations;
  v_table_ids uuid[];
  was_requested boolean;
  tid uuid;
begin
  select * into r from atlas_private.reservations where id = p_reservation_id;
  if r.id is null then raise exception 'Booking not found.' using errcode = 'P0002', hint = 'atlas:not_found'; end if;
  if r.status in ('cancelled','no_show','completed') then
    raise exception 'This booking can no longer be moved.' using errcode = '22023', hint = 'atlas:invalid_request';
  end if;
  if pg_catalog.jsonb_typeof(p_table_ids) <> 'array' then
    raise exception 'Choose at least one table.' using errcode = '22023', hint = 'atlas:invalid_request';
  end if;
  select pg_catalog.array_agg((value #>> '{}')::uuid) into v_table_ids
  from pg_catalog.jsonb_array_elements(p_table_ids) value;
  if v_table_ids is null or pg_catalog.array_length(v_table_ids, 1) < 1 then
    raise exception 'Choose at least one table.' using errcode = '22023', hint = 'atlas:invalid_request';
  end if;

  -- S106: a multi-stool allocation must be one adjacent group within a single
  -- seating section — never a cross-section combination (e.g. Bar 8 + Bar 9).
  if not atlas_private.booking_tables_contiguous_segment(v_table_ids) then
    raise exception 'Those stools are not one adjacent group within a single seating section.'
      using errcode = '22023', hint = 'atlas:invalid_request';
  end if;

  perform 1 from atlas_private.booking_tables t where t.id = any(v_table_ids) order by t.id for update;
  foreach tid in array v_table_ids loop
    if not exists (select 1 from atlas_private.booking_tables t where t.id = tid) then
      raise exception 'A chosen table does not exist.' using errcode = '22023', hint = 'atlas:invalid_request';
    end if;
    if not atlas_private.booking_table_free(tid, r.start_at, r.end_at, r.id) then
      raise exception 'That table is not free for this booking''s time.' using errcode = '23505', hint = 'atlas:conflict';
    end if;
  end loop;

  update atlas_private.reservation_tables set released_at = pg_catalog.now()
  where reservation_id = r.id and released_at is null;
  foreach tid in array v_table_ids loop
    insert into atlas_private.reservation_tables (reservation_id, table_id, start_at, end_at)
    values (r.id, tid, r.start_at, r.end_at);
  end loop;

  was_requested := r.status = 'requested';
  if was_requested then
    update atlas_private.reservations set status = 'confirmed' where id = r.id;
    insert into atlas_private.reservation_status_history (reservation_id, from_status, to_status, changed_by, changed_by_label, changed_by_role, note)
    values (r.id, 'requested', 'confirmed', p_actor_id, label, p_actor_role, 'assigned tables');
  end if;
  insert into atlas_private.booking_events (event_type, reservation_id, actor_id, actor_label, actor_role, payload)
  values ('reservation_assigned', r.id, p_actor_id, label, p_actor_role, pg_catalog.jsonb_build_object('tables', pg_catalog.to_jsonb(v_table_ids)));
  return pg_catalog.jsonb_build_object('reservation', atlas_private.booking_reservation_json(r.id));
exception
  when invalid_text_representation then
    raise exception 'Invalid table selection.' using errcode = '22023', hint = 'atlas:invalid_request';
end
$function$;
revoke all on function public.atlas_bookings_assign(uuid, text, uuid, jsonb) from public, anon, authenticated;
grant execute on function public.atlas_bookings_assign(uuid, text, uuid, jsonb) to service_role;

-- 5. Per-day last start from the venue's closing time ------------------------
-- Returns the latest local start time (minutes from the business day's midnight)
-- at which a reservation of p_duration_minutes still finishes by that weekday's
-- close, or NULL when the venue is closed that day. close_next_day means the
-- close is after midnight (e.g. 01:00 = 25:00). weekday: 0 = Sunday.
create or replace function atlas_private.booking_day_last_start_minutes(
  p_weekday smallint, p_duration_minutes integer
)
returns integer
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  h atlas_private.settings_business_hours;
  close_minutes integer;
begin
  select * into h from atlas_private.settings_business_hours where weekday = p_weekday;
  if not found or not h.is_open or h.close_time is null then return null; end if;
  close_minutes := (extract(hour from h.close_time) * 60 + extract(minute from h.close_time))::int
                   + case when h.close_next_day then 1440 else 0 end;
  return close_minutes - coalesce(p_duration_minutes, 120);
end
$function$;
revoke all on function atlas_private.booking_day_last_start_minutes(smallint, integer)
  from public, anon, authenticated;
